"""Offline screenshots of the website components generated by the website build."""
import json
from pathlib import Path


def script_json(value):
    return json.dumps(value, ensure_ascii=True, allow_nan=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')


def document(detail, kind, review=''):
    bundle=json.loads(Path(__file__).with_name('website.json').read_text(encoding='utf-8'))
    view=detail.get('webView')
    if kind=='data' and not isinstance(view,dict):
        raise ValueError('Website view missing; update website API')
    payload={**(view or {}),'kind':kind,'index':detail.get('index'),'mapName':detail.get('mapName'),'review':review}
    # Only the repository-owned bundle contains executable code. All API text is JSON-escaped.
    content=bundle[kind]
    support='<div id="chart" hidden></div><section id="performancePanel" hidden></section>'
    return '<!doctype html><html lang="zh-CN"><meta charset="utf-8"><style>'+bundle['css']+'main.capture{width:1440px;max-width:none;padding:24px;margin:0}.capture .table-wrap{overflow:visible}</style><main class="capture results">'+content+'</main>'+support+'<script>const INPUT='+script_json(payload)+';</script><script>'+bundle['script']+'</script></html>'


def data_document(detail):
    return document(detail,'data')


def review_documents(detail,review):
    body=str(review.get('text') or '')
    if not body.strip() or len(body)>24000:
        raise ValueError('Invalid AI review length')
    # Keep the website card and typography on every page; never truncate returned text.
    return [document(detail,'review',body[i:i+3000]) for i in range(0,len(body),3000)]
